mapper.select:
SELECT current_reading FROM smt_ele_meter_history WHERE is_delete = 0 AND ele_meter_id = #{meterId}
AND collect_time >= to_date( #{meterMonth}, 'yyyy-mm-dd hh24:mi:ss' )
order by collect_time asc

SELECT * FROM (
	SELECT ID, ELE_METER_ID, COLLECT_TIME, CURRENT_READING, IS_ERROR
	FROM SMT_ELE_METER_HISTORY
	WHERE IS_DELETE = 0 AND ELE_METER_ID = #{meterId}
	ORDER BY COLLECT_TIME DESC, ID DESC
) WHERE ROWNUM = 1
